'use client';

import { useEffect, useState } from 'react';
import { api, uploadFile } from '@/lib/api';
import { Plus, Edit, Trash2, Eye, Send, CheckCircle } from 'lucide-react';
import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import Placeholder from '@tiptap/extension-placeholder';

const STRAPI_URL =
  process.env.NEXT_PUBLIC_STRAPI_URL || 'http://localhost:1337';
const FRONTEND_URL =
  process.env.NEXT_PUBLIC_WEB_URL || 'http://localhost:3000';

interface Category {
  id: string;
  documentId: string;
  name: string;
}

interface Article {
  id: string;
  documentId: string;
  title: string;
  slug: string;
  summary?: string;
  content?: string;
  review_status: 'draft' | 'pending' | 'approved' | 'published' | 'rejected';
  publish_time?: string;
  category?: { documentId: string };
  cover?: { id: string; url: string };
}

function MenuBar({ editor }: { editor: any }) {
  if (!editor) return null;
  const btn = (active: boolean) =>
    `px-2 py-1 rounded text-sm ${active ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-600'}`;

  return (
    <div className="flex flex-wrap gap-2 mb-3">
      <button className={btn(editor.isActive('bold'))} onClick={() => editor.chain().focus().toggleBold().run()}>B</button>
      <button className={btn(editor.isActive('italic'))} onClick={() => editor.chain().focus().toggleItalic().run()}>I</button>
      <button className={btn(editor.isActive('heading', { level: 2 }))} onClick={() => editor.chain().focus().toggleHeading({ level: 2 }).run()}>H2</button>
      <button className={btn(editor.isActive('bulletList'))} onClick={() => editor.chain().focus().toggleBulletList().run()}>• 列表</button>
      <button className={btn(editor.isActive('orderedList'))} onClick={() => editor.chain().focus().toggleOrderedList().run()}>1. 列表</button>
      <button className={btn(editor.isActive('blockquote'))} onClick={() => editor.chain().focus().toggleBlockquote().run()}>引用</button>
      <button className="px-2 py-1 rounded text-sm bg-gray-200" onClick={() => editor.chain().focus().undo().run()}>撤销</button>
      <button className="px-2 py-1 rounded text-sm bg-gray-200" onClick={() => editor.chain().focus().redo().run()}>重做</button>
    </div>
  );
}

export default function ArticlesPage() {
  const [articles, setArticles] = useState<Article[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [loading, setLoading] = useState(true);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingDocId, setEditingDocId] = useState<string | null>(null);

  const [form, setForm] = useState({
    title: '',
    summary: '',
    content: '',
    categoryId: '',
    coverId: '',
    coverPreview: '',
  });

  const [coverFile, setCoverFile] = useState<File | null>(null);

  const editor = useEditor({
    extensions: [
      StarterKit,
      Placeholder.configure({ placeholder: '请输入正文内容…' }),
    ],
    content: form.content || '',
    onUpdate: ({ editor }) => {
      setForm((f) => ({ ...f, content: editor.getHTML() }));
    },
  });

   
  useEffect(() => {
    fetchArticles();
    fetchCategories();
  }, []);

  const fetchArticles = async () => {
    setLoading(true);
    const res = (await api.getArticles(
      '?populate=category,cover&sort=publish_time:desc'
    )) as { data?: Article[] };
    setArticles(res.data || []);
    setLoading(false);
  };

  const fetchCategories = async () => {
    const res = (await api.getCategories('?sort=sort_order:asc')) as { data?: Category[] };
    setCategories(res.data || []);
  };

  const openModal = async (docId?: string) => {
    if (docId) {
      const res = (await api.getArticle(docId)) as { data?: Article };
      const a = res.data;
      if (a) {
        setEditingDocId(docId);
        setForm({
          title: a.title || '',
          summary: a.summary || '',
          content: a.content || '',
          categoryId: a.category?.documentId || '',
          coverId: a.cover?.id || '',
          coverPreview: a.cover?.url ? STRAPI_URL + a.cover.url : '',
        });
      }
    } else {
      setEditingDocId(null);
      setForm({
        title: '',
        summary: '',
        content: '',
        categoryId: '',
        coverId: '',
        coverPreview: '',
      });
    }
    setCoverFile(null);
    setIsModalOpen(true);

    // 初始化编辑器内容
    setTimeout(() => {
      editor?.commands.setContent(docId ? form.content : '', false);
    }, 0);
  };

  const closeModal = () => setIsModalOpen(false);

  const saveArticle = async (e: React.FormEvent) => {
    e.preventDefault();

    let coverId = form.coverId;

    if (coverFile) {
      const uploaded = (await uploadFile(coverFile)) as { id: string; url: string }[];
      if (uploaded?.[0]?.id) coverId = uploaded[0].id;
    }

    const payload = {
      title: form.title,
      summary: form.summary,
      content: form.content,
      category: form.categoryId || null,
      cover: coverId || null,
      review_status: 'draft',
    };

    if (editingDocId) await api.updateArticle(editingDocId, payload);
    else await api.createArticle(payload);

    closeModal();
    fetchArticles();
  };

  const submitForReview = async (docId: string) => {
    await api.updateArticle(docId, { review_status: 'pending' });
    fetchArticles();
  };

  const publish = async (docId: string) => {
    await api.updateArticle(docId, {
      review_status: 'published',
      publish_time: new Date().toISOString(),
    });
    fetchArticles();
  };

  const handleDelete = async (docId: string) => {
    if (!confirm('确定删除这篇文章吗？')) return;
    await api.deleteArticle(docId);
    fetchArticles();
  };

  const getStatusBadge = (status: Article['review_status']) => {
    const map: any = {
      draft: { label: '草稿', color: 'bg-gray-100 text-gray-600' },
      pending: { label: '待审核', color: 'bg-amber-100 text-amber-600' },
      approved: { label: '已通过', color: 'bg-blue-100 text-blue-600' },
      published: { label: '已发布', color: 'bg-emerald-100 text-emerald-600' },
      rejected: { label: '已驳回', color: 'bg-red-100 text-red-600' },
    };
    const info = map[status];
    return (
      <span className={`inline-block px-3 py-1 rounded-full text-xs font-medium ${info.color}`}>
        {info.label}
      </span>
    );
  };

  return (
    <div className="space-y-6">
      {/* 标题 + 新增 */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">文章管理</h1>
          <p className="text-gray-500 mt-1">共 {articles.length} 条文章</p>
        </div>
        <button
          onClick={() => openModal()}
          className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-2xl font-medium transition-all"
        >
          <Plus className="w-5 h-5" />
          新增文章
        </button>
      </div>

      {/* 列表 */}
      {loading ? (
        <div className="text-center py-12 text-gray-400">加载中...</div>
      ) : (
        <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
          <table className="w-full">
            <thead className="bg-gray-50 border-b">
              <tr>
                <th className="px-6 py-4 text-left text-sm font-medium text-gray-500">标题</th>
                <th className="px-6 py-4 text-left text-sm font-medium text-gray-500">状态</th>
                <th className="px-6 py-4 text-left text-sm font-medium text-gray-500">发布时间</th>
                <th className="px-6 py-4 text-center text-sm font-medium text-gray-500">操作</th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {articles.map((article) => (
                <tr key={article.id} className="hover:bg-gray-50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="font-medium text-gray-900">{article.title}</div>
                    <div className="text-xs text-gray-400">slug: {article.slug}</div>
                  </td>
                  <td className="px-6 py-4">{getStatusBadge(article.review_status)}</td>
                  <td className="px-6 py-4 text-sm text-gray-500">
                    {article.publish_time
                      ? new Date(article.publish_time).toLocaleDateString('zh-CN')
                      : '未发布'}
                  </td>
                  <td className="px-6 py-4 text-center">
                    <div className="flex items-center justify-center gap-3 flex-wrap">
                      <a
                        href={`${FRONTEND_URL}/article/${article.slug}`}
                        target="_blank"
                        className="text-indigo-600 hover:text-indigo-700"
                      >
                        <Eye className="w-5 h-5" />
                      </a>
                      <button onClick={() => openModal(article.documentId)} className="text-blue-600 hover:text-blue-700">
                        <Edit className="w-5 h-5" />
                      </button>
                      {(article.review_status === 'draft' || article.review_status === 'rejected') && (
                        <button onClick={() => submitForReview(article.documentId)} className="text-amber-600 hover:text-amber-700">
                          <Send className="w-5 h-5" />
                        </button>
                      )}
                      {article.review_status === 'approved' && (
                        <button onClick={() => publish(article.documentId)} className="text-green-600 hover:text-green-700">
                          <CheckCircle className="w-5 h-5" />
                        </button>
                      )}
                      <button onClick={() => handleDelete(article.documentId)} className="text-red-500 hover:text-red-600">
                        <Trash2 className="w-5 h-5" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {articles.length === 0 && (
                <tr>
                  <td colSpan={4} className="p-6 text-center text-gray-400">暂无文章</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* 编辑弹窗 */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-4xl mx-4 p-8">
            <h2 className="text-2xl font-bold mb-6">
              {editingDocId ? '编辑文章' : '新增文章'}
            </h2>

            <form onSubmit={saveArticle} className="space-y-6">
              <input
                className="w-full px-4 py-3 border rounded"
                placeholder="标题"
                value={form.title}
                onChange={(e) => setForm({ ...form, title: e.target.value })}
                required
              />

              <textarea
                className="w-full px-4 py-3 border rounded"
                placeholder="摘要"
                rows={2}
                value={form.summary}
                onChange={(e) => setForm({ ...form, summary: e.target.value })}
              />

              <div>
                <label className="block mb-2 font-medium">正文内容</label>
                <MenuBar editor={editor} />
                <div className="border rounded p-2 min-h-[200px]">
                  <EditorContent editor={editor} />
                </div>
              </div>

              <div>
                <label className="block mb-2 font-medium">所属栏目</label>
                <select
                  value={form.categoryId}
                  onChange={(e) => setForm({ ...form, categoryId: e.target.value })}
                  className="w-full px-4 py-3 border rounded"
                >
                  <option value="">请选择栏目</option>
                  {categories.map((c) => (
                    <option key={c.documentId} value={c.documentId}>
                      {c.name}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block mb-2 font-medium">封面图</label>
                {form.coverPreview && (
                  <img src={form.coverPreview} className="w-40 h-24 object-cover rounded mb-2" />
                )}
                <input
                  type="file"
                  accept="image/*"
                  onChange={(e) => setCoverFile(e.target.files?.[0] || null)}
                />
              </div>

              <div className="flex justify-end gap-4">
                <button type="button" onClick={closeModal} className="px-6 py-3 border rounded">
                  取消
                </button>
                <button type="submit" className="px-6 py-3 bg-blue-600 text-white rounded">
                  保存
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
